#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    long long minOperationsToMakeEqual(std::vector<int>& nums, int k) {
        int rem = nums[0] % k;
        std::vector<int> scaled;
        for (int x : nums) {
            if (x % k != rem) return -1;
            scaled.push_back(x / k);
        }
        std::sort(scaled.begin(), scaled.end());
        int median = scaled[scaled.size() / 2];
        long long ops = 0;
        for (int v : scaled) ops += std::abs(v - median);
        return ops;
    }
};

import java.util.*;

class Solution {
    public long minOperationsToMakeEqual(int[] nums, int k) {
        int rem = nums[0] % k;
        int n = nums.length;
        int[] scaled = new int[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] % k != rem) return -1;
            scaled[i] = nums[i] / k;
        }
        Arrays.sort(scaled);
        int median = scaled[n / 2];
        long ops = 0;
        for (int v : scaled) ops += Math.abs(v - median);
        return ops;
    }
}

function minOperationsToMakeEqual(nums, k) {
    const rem = nums[0] % k;
    const scaled = [];
    for (const x of nums) {
        if (x % k !== rem) return -1;
        scaled.push(Math.floor(x / k));
    }
    scaled.sort((a, b) => a - b);
    const median = scaled[Math.floor(scaled.length / 2)];
    let ops = 0;
    for (const v of scaled) ops += Math.abs(v - median);
    return ops;
}
